export function tco(p,egress=1,backups=true,strict=false){if(p.price_mo==null)return null;const f0=P[p.provider_id].fees,f=strict?{...f0,ipv4:f0.ipv4_s==='verified'?f0.ipv4:0,backup_pct:f0.backup_s==='verified'?f0.backup_pct:0,overage:f0.overage_s==='verified'?f0.overage:(p.transfer_tb===0?null:0)}:f0,k=p.currency==='EUR'?FX_EUR_USD:1;const base=p.price_mo*k;
 const ip=f.ipv4??0,bk=backups?(p.backup_mo!=null?p.backup_mo:f.backup_pct!=null?base*f.backup_pct/100:0):0;let ov=0;
 if(p.transfer_tb!=null&&egress>p.transfer_tb){if(f.overage==null)return null;ov=(egress-p.transfer_tb)*1000*f.overage*(f.cur==='EUR'?FX_EUR_USD:1)}return {base,ip,bk,ov,total:base+ip+bk+ov}}
