// ---- Providers
const rankFor=(s,eg=EG)=>ver.filter(p=>equiv(p,s)).map(p=>({p,t:tco(p,eg,true,true)})).filter(x=>x.t).sort((a,b)=>a.t.total-b.t.total);
const verdictFor=id=>SPECS.map(s=>{const r=rankFor(s);const i=r.findIndex(x=>x.p.provider_id===id);if(i<0)return `<li>${s.cpu} vCPU / ${s.ram} GB: no verified equivalent plan tracked.</li>`;const me=r[i],best=r[0];return `<li><b>${s.cpu} vCPU / ${s.ram} GB:</b> ${esc(me.p.plan)} at ${usd(me.t.total)}/mo ranks #${i+1} of ${r.length}. ${i===0?`Cheapest tracked${r[1]?` — ${yr(r[1].t.total-me.t.total)}/yr less than #2 (${esc(r[1].p.provider)})`:''}.`:`${yr(me.t.total-best.t.total)}/yr more than the cheapest (${esc(best.p.provider)} ${esc(best.p.plan)}).`}</li>`}).join('');
for(const pr of providers){const ps=plans.filter(p=>p.provider_id===pr.id),f=pr.fees;
 page({file:`providers/${pr.id}.html`,og:'p-'+pr.id,title:`${pr.name} VPS pricing — true monthly cost | ${NAME}`,desc:`${pr.name} VPS plans with IPv4, backup and bandwidth costs added, ranked against ${providers.length-1} other providers. Source checked ${pr.checked}.`,body:`
<section class="hero"><div class="eyebrow">Provider</div><h1>${esc(pr.name)}</h1><p class="lede">Source: <a href="${pr.source}" rel="noopener">${esc(pr.source.replace(/^https?:\/\//,''))}</a>, checked ${pr.checked}. <a href="${aff(pr.id)}" rel="sponsored noopener">Visit ${esc(pr.name)}</a></p></section>
<div class="verdict"><div class="eyebrow">Verdict · ${EG} TB egress, backups on</div><ul>${verdictFor(pr.id)}</ul><p class="note">${asOf}. ${meth}.</p></div>
<div class="tbl"><table><thead><tr><th>Plan</th><th>Tier</th><th class="n">vCPU</th><th class="n">RAM</th><th class="n">Disk</th><th class="n">Incl. TB</th><th class="n">List / mo</th><th class="n">Intro</th><th class="n">True @1TB</th><th class="n">True @5TB</th><th>Status</th><th>Notes</th></tr></thead><tbody>${ps.map(p=>{const a=tco(p,1),b=tco(p,5);return `<tr><td>${esc(p.plan)}</td><td>${p.tier}</td><td class="n">${p.vcpu??'—'}</td><td class="n">${p.ram_gb??'—'}</td><td class="n">${p.disk_gb??'—'}</td><td class="n">${p.transfer_tb??'∞/?'}</td><td class="n">${p.price_mo==null?'—':(p.currency==='EUR'?'€':'$')+p.price_mo.toFixed(2)}</td><td class="n">${p.promo_mo?'$'+p.promo_mo.toFixed(2):'—'}</td><td class="n">${usd(a?.total)}</td><td class="n">${usd(b?.total)}</td><td>${tag(p.status)}</td><td style="white-space:normal;min-width:220px" class="src">${esc(p.notes)}</td></tr>`}).join('')}</tbody></table></div>
<h2>Fees that change the bill</h2><dl class="kv"><dt>IPv4</dt><dd>${f.ipv4==null?'not published':usd(f.ipv4)+'/mo'} · ${esc(f.ipv4_n)} ${tag(f.ipv4_s)}</dd><dt>Backups</dt><dd>${f.backup_pct!=null?f.backup_pct+'% of plan':'see plan'} · ${esc(f.backup_n)} ${tag(f.backup_s)}</dd><dt>Overage</dt><dd>${f.overage==null?'not published':(f.cur==='EUR'?'€':'$')+f.overage+'/GB'} · ${esc(f.overage_n)} ${tag(f.overage_s)}</dd></dl>
${mailBox('p',`Get alerted if ${pr.name} changes prices`,`Watch ${pr.name} for me`)}`});}
page({file:'providers/index.html',title:`VPS providers tracked | ${NAME}`,desc:`All ${providers.length} VPS providers in ${NAME} with plan counts and sources.`,body:`<section class="hero"><div class="eyebrow">Providers</div><h1>${providers.length} providers</h1></section><div class="tbl"><table><thead><tr><th>Provider</th><th class="n">Plans</th><th class="n">Verified</th><th class="n">Cheapest true / mo</th><th>Source · checked</th></tr></thead><tbody>${providers.map(pr=>{const ps=plans.filter(p=>p.provider_id===pr.id),m=Math.min(...ps.map(p=>tco(p,1)?.total??Infinity));return `<tr><td><a href="/providers/${pr.id}.html">${esc(pr.name)}</a></td><td class="n">${ps.length}</td><td class="n">${ps.filter(p=>p.status==='verified').length}</td><td class="n">${isFinite(m)?usd(m):'—'}</td><td class="src"><a href="${pr.source}">source</a> · ${pr.checked}</td></tr>`}).join('')}</tbody></table></div>`});
// ---- Compare pairs
const MAJOR=['digitalocean','vultr','linode','hetzner','ovhcloud','lightsail','hostinger','upcloud','dreamhost','kamatera'];const pairs=[];
for(let i=0;i<MAJOR.length;i++)for(let j=i+1;j<MAJOR.length;j++)pairs.push([P[MAJOR[i]],P[MAJOR[j]]]);
const best=(id,tier,eg)=>plans.filter(p=>p.provider_id===id&&p.tier===tier).map(p=>({p,t:tco(p,eg)})).filter(x=>x.t).sort((a,b)=>a.t.total-b.t.total)[0];
const pairVerdict=(a,b)=>SPECS.map(s=>{const r=rankFor(s),x=r.find(z=>z.p.provider_id===a.id),y=r.find(z=>z.p.provider_id===b.id);if(!x||!y)return `<li>${s.cpu} vCPU / ${s.ram} GB: ${!x&&!y?'neither has':(!x?esc(a.name):esc(b.name))+' has no'} verified equivalent plan tracked.</li>`;const [w,l]=x.t.total<=y.t.total?[x,y]:[y,x];return `<li><b>Cheapest for ${s.cpu} vCPU / ${s.ram} GB: ${esc(w.p.provider)}</b> (${esc(w.p.plan)}, ${usd(w.t.total)}/mo) — ${yr(l.t.total-w.t.total)}/yr less than ${esc(l.p.provider)} ${esc(l.p.plan)}.</li>`}).join('');
for(const [a,b] of pairs){const slug=`${a.id}-vs-${b.id}`;const rows=[['entry',1],['entry',5],['mid',1],['mid',5]].map(([tier,eg])=>{const x=best(a.id,tier,eg),y=best(b.id,tier,eg);const w=x&&y?(x.t.total<=y.t.total?0:1):-1;const cell=(z,me)=>z?`<td class="n${w===me?' win':''}">${usd(z.t.total)}<br><span class="src">${esc(z.p.plan)} · ${z.p.vcpu??'?'} vCPU / ${z.p.ram_gb??'?'} GB ${z.p.status!=='verified'?'· unverified':''}</span></td>`:'<td class="n">—</td>';return `<tr><td>${tier} · ${eg} TB egress</td>${cell(x,0)}${cell(y,1)}</tr>`}).join('');
 const cmpAnswer=(()=>{const bits=SPECS.map(s=>{const r=rankFor(s),x=r.find(z=>z.p.provider_id===a.id),y=r.find(z=>z.p.provider_id===b.id);if(!x||!y)return null;const [w,l]=x.t.total<=y.t.total?[x,y]:[y,x];return `${esc(w.p.provider)} wins ${s.cpu}/${s.ram} GB at ${usd(w.t.total)}/mo (${yr(l.t.total-w.t.total)}/yr less than ${esc(l.p.provider)})`}).filter(Boolean);return bits.length?`As of ${lastChecked}, at ${EG} TB egress with backups: ${bits.join('; ')}.`:`As of ${lastChecked}, one or both providers lack a verified equivalent plan for the headline specs.`})();
 const cmpFaq=[['Which is cheaper?',cmpAnswer.replace(/<[^>]+>/g,'')],['Last verified?',lastChecked],['What does true monthly cost include?','List/renewal + IPv4 + backups + overage at the chosen egress.']];
 page({file:`compare/${slug}.html`,og:'compare',title:`${a.name} vs ${b.name} — VPS true monthly cost | ${NAME}`,desc:`${a.name} vs ${b.name}: which is cheaper for 2 vCPU / 4 GB and 4 vCPU / 8 GB once IPv4, backups and bandwidth are counted, and by how much per year.`,ld:[ORG_LD,{'@context':'https://schema.org','@type':'FAQPage',mainEntity:cmpFaq.map(([q,a])=>({'@type':'Question',name:q,acceptedAnswer:{'@type':'Answer',text:a}}))},{'@context':'https://schema.org','@type':'BreadcrumbList',itemListElement:[{'@type':'ListItem',position:1,name:'Home',item:SITE+'/'},{'@type':'ListItem',position:2,name:'Compare',item:SITE+'/compare/'},{'@type':'ListItem',position:3,name:`${a.name} vs ${b.name}`,item:SITE+`/compare/${slug}.html`}]}],body:`
<section class="hero"><div class="eyebrow"><a href="/compare/">Compare</a> · head to head · last verified ${lastChecked}</div><h1>${esc(a.name)} vs ${esc(b.name)}</h1>
<p class="lede"><b>Answer:</b> ${cmpAnswer}</p></section>
<div class="panel"><div class="eyebrow">Key stats</div><ul style="margin:10px 0 0;padding-left:18px">${SPECS.map(s=>{const r=rankFor(s),x=r.find(z=>z.p.provider_id===a.id),y=r.find(z=>z.p.provider_id===b.id);if(!x||!y)return `<li>${s.cpu}/${s.ram} GB: incomplete data</li>`;const [w,l]=x.t.total<=y.t.total?[x,y]:[y,x];return `<li><b>${s.cpu} vCPU / ${s.ram} GB:</b> ${esc(w.p.provider)} ${esc(w.p.plan)} ${usd(w.t.total)}/mo vs ${esc(l.p.provider)} ${usd(l.t.total)}/mo (${yr(l.t.total-w.t.total)}/yr gap)</li>`}).join('')}<li><b>Last verified:</b> ${lastChecked}</li></ul></div>
<div class="verdict"><div class="eyebrow">Verdict · ${EG} TB egress, backups on, verified plans</div><ul>${pairVerdict(a,b)}</ul><p class="note">${asOf}. ${meth}.</p></div>
<h2>By tier and egress</h2><div class="tbl"><table><thead><tr><th>Scenario</th><th class="n">${esc(a.name)}</th><th class="n">${esc(b.name)}</th></tr></thead><tbody>${rows}</tbody></table></div>
<div class="grid2">${[a,b].map(x=>`<div class="panel"><h3><a href="/providers/${x.id}.html">${esc(x.name)}</a></h3><dl class="kv"><dt>IPv4</dt><dd>${esc(x.fees.ipv4_n)}</dd><dt>Backups</dt><dd>${esc(x.fees.backup_n)}</dd><dt>Overage</dt><dd>${esc(x.fees.overage_n)}</dd></dl><p class="src">Source: <a href="${x.source}">${esc(x.source.replace(/^https?:\/\//,''))}</a> · ${x.checked}</p><a class="btn ghost" href="${aff(x.id)}" rel="sponsored noopener">Visit ${esc(x.name)}</a></div>`).join('')}</div>
${mailBox('c',`Get alerted if ${a.name} or ${b.name} changes prices`,'Watch this pair for me')}`});}
page({file:'compare/index.html',og:'compare',title:`VPS provider comparisons — ${pairs.length} head-to-heads | ${NAME}`,desc:'Head-to-head true monthly cost for every pair of major VPS providers.',body:`<section class="hero"><div class="eyebrow">Compare</div><h1>Head to head, on the whole bill.</h1><p class="lede">${pairs.length} pairings of ${MAJOR.length} major providers, each with a verdict and the annual difference.</p></section><div class="pairs">${pairs.map(([a,b])=>`<a href="/compare/${a.id}-vs-${b.id}.html">${esc(a.name)} vs ${esc(b.name)}</a>`).join('')}</div>${mailBox('ci','The cheapest plan for your specs, weekly','Send me the weekly ledger')}`});
