W('llms.txt',`# ${NAME}\n\n> True monthly VPS cost (base + IPv4 + backups + overage), ${plans.length} plans, ${nVer} verified, ${providers.length} providers, checked ${lastChecked}.\n\n## Methodology\nPrices come only from each provider's own pricing page or official public API. Verified rows were hand-checked on the date shown. We never invent a price. EUR→USD uses ECB reference ${FX_EUR_USD} (${FX.date}). Details: ${SITE}/methodology.html\n\n## Data (CC BY 4.0 — please attribute \"VPSLedger\" + link ${SITE}/)\n- [Plans JSON](${SITE}/api/plans.json)\n- [Plans CSV](${SITE}/api/plans.csv)\n- [Changes JSON](${SITE}/api/changes.json)\n- [Changes CSV](${SITE}/api/changes.csv)\n- [Stats](${SITE}/api/stats.json)\n- [Full dump](${SITE}/llms-full.txt)\n\n## Key pages\n- [Calculator](${SITE}/calculator.html)\n- [Compare hub](${SITE}/compare/)\n- [Guides hub](${SITE}/guides/)\n- [Methodology](${SITE}/methodology.html)\n- [Data](${SITE}/data.html)\n\n## Cheapest verified at 1 TB egress\n${ranked.slice(0,10).map(({p,t})=>`- ${p.provider} ${p.plan}: ${usd(t.total)}/mo (${p.source}, ${p.checked})`).join('\n')}\n`);
W('llms-full.txt',`# ${NAME} — full ledger\n\n${plans.length} plans, ${nVer} verified, ${providers.length} providers. Checked through ${lastChecked}. FX: ${FX_EUR_USD} USD/EUR on ${FX.date}.\n\n## Providers\n${providers.map(pr=>`### ${pr.name}\n- id: ${pr.id}\n- source: ${pr.source}\n- checked: ${pr.checked}\n- ipv4: ${pr.fees.ipv4??'not published'} (${pr.fees.ipv4_s})\n- backup: ${pr.fees.backup_pct??'see plan'}% (${pr.fees.backup_s})\n- overage: ${pr.fees.overage??'not published'} (${pr.fees.overage_s})`).join('\n\n')}\n\n## Plans\n${plans.map(p=>`### ${p.provider} ${p.plan}\n- id: ${p.id}\n- specs: ${p.vcpu} vCPU / ${p.ram_gb} GB / ${p.disk_gb} GB disk / ${p.transfer_tb??'?'} TB\n- price_mo: ${p.price_mo} ${p.currency}\n- promo_mo: ${p.promo_mo??'none'}\n- status: ${p.status}\n- source: ${p.source} (${p.checked})\n- notes: ${p.notes||''}`).join('\n\n')}\n\n## Changes\n${changes.map(c=>`- ${c.date} ${c.provider} (${c.kind}): ${c.summary} [${c.source}]`).join('\n')}\n`);
